import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.A5mep7Fe.js";const h=JSON.parse('{"title":"🔄 01 · Agent 架构范式（ReAct / Plan-and-Execute / Reflexion）","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/01-Agent架构范式.md","filePath":"03-算法岗-AI-Agent/01-Agent架构范式.md","lastUpdated":1786806808000}'),l={name:"03-算法岗-AI-Agent/01-Agent架构范式.md"};function r(s,t,i,c,d,p){return n(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="🔄-01-·-agent-架构范式-react-plan-and-execute-reflexion" tabindex="-1">🔄 01 · Agent 架构范式（ReAct / Plan-and-Execute / Reflexion） <a class="header-anchor" href="#🔄-01-·-agent-架构范式-react-plan-and-execute-reflexion" aria-label="Permalink to &quot;🔄 01 · Agent 架构范式（ReAct / Plan-and-Execute / Reflexion）&quot;">​</a></h1><blockquote><p>Agent 的「大脑运转方式」。面试最爱问「为什么选 ReAct 而不是 Plan-and-Execute」——本题考的是<strong>架构权衡判断力</strong>。</p></blockquote><hr><h2 id="一、react-reasoning-acting-⭐-最经典" tabindex="-1">一、ReAct（Reasoning + Acting）⭐ 最经典 <a class="header-anchor" href="#一、react-reasoning-acting-⭐-最经典" aria-label="Permalink to &quot;一、ReAct（Reasoning + Acting）⭐ 最经典&quot;">​</a></h2><p><strong>思想</strong>：把「思考（Thought）→ 行动（Action）→ 观察（Observation）」串成循环。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: 我需要查天气，先调用天气工具</span></span>
<span class="line"><span>Action: get_weather(city=&quot;北京&quot;)</span></span>
<span class="line"><span>Observation: 北京 25°C 晴</span></span>
<span class="line"><span>Thought: 已知答案，回复用户</span></span>
<span class="line"><span>Action: Final Answer: 北京今天25°C晴</span></span></code></pre></div><ul><li>每步基于<strong>当前观察</strong>动态决策，<strong>强交互、强适应</strong>。</li><li>天然兼容 Function Calling。</li></ul><p><strong>优点</strong>：灵活、可处理突发情况、易用 few-shot 调。 <strong>缺点</strong>：长任务易「走偏/循环」、缺乏全局规划、token 消耗大。</p><hr><h2 id="二、plan-and-execute-先规划再执行" tabindex="-1">二、Plan-and-Execute（先规划再执行） <a class="header-anchor" href="#二、plan-and-execute-先规划再执行" aria-label="Permalink to &quot;二、Plan-and-Execute（先规划再执行）&quot;">​</a></h2><p><strong>思想</strong>：先用一个「规划器」把任务拆成步骤计划，再逐步执行；执行中可重规划。</p><ul><li>适合<strong>复杂、长链条、可预见的任务</strong>（如「调研+写报告」）。</li><li>代表：Plan-and-Solve、LangGraph 的 plan 模式。</li></ul><p><strong>优点</strong>：有全局观、不易跑偏、可并行子任务。 <strong>缺点</strong>：初始计划可能不准、对动态环境适应性弱、规划器本身可能出错。</p><hr><h2 id="三、reflexion-反思-自我修正" tabindex="-1">三、Reflexion（反思/自我修正） <a class="header-anchor" href="#三、reflexion-反思-自我修正" aria-label="Permalink to &quot;三、Reflexion（反思/自我修正）&quot;">​</a></h2><p><strong>思想</strong>：Agent 执行后<strong>自我反思</strong>失败原因，把反思写进记忆，下一轮改进。</p><ul><li>常用于代码生成、需要迭代优化的任务。</li><li>关键：把「错误+反思」作为额外上下文反馈给模型。</li></ul><hr><h2 id="四、范式对比与选型-⭐-面试核心" tabindex="-1">四、范式对比与选型（⭐ 面试核心） <a class="header-anchor" href="#四、范式对比与选型-⭐-面试核心" aria-label="Permalink to &quot;四、范式对比与选型（⭐ 面试核心）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范式</th><th>适配场景</th><th>不擅长</th></tr></thead><tbody><tr><td>ReAct</td><td>实时交互、工具调用、动态任务</td><td>很长/需严格顺序的任务</td></tr><tr><td>Plan-and-Execute</td><td>复杂多步、可规划任务</td><td>高度不确定/需即时反应</td></tr><tr><td>Reflexion</td><td>可验证、需迭代（代码/搜索）</td><td>一步即得的简单任务</td></tr><tr><td>ReAct + 反思</td><td>大多数生产场景（主流组合）</td><td>极低成本要求</td></tr></tbody></table><p><strong>选型判断框架</strong>：</p><ol><li>任务是否可预先规划？→ 是：Plan-and-Execute；否：ReAct。</li><li>是否需要从错误中学习？→ 是：加 Reflexion。</li><li>成本/延迟敏感？→ 减少反思轮次、用轻量规划。</li></ol><hr><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：为什么选 ReAct 而不是 Plan-and-Execute？（经典题）</strong></p><blockquote><p>看场景。实时客服/工具调用这类需动态适应、无法预先规划的任务 → ReAct；长链条研究写作类可先规划 → Plan-and-Execute。生产常「Plan 打底 + ReAct 执行 + Reflexion 纠错」混合。还可在 ReAct 中加 few-shot 让它近似规划，灵活性与可预测性权衡。</p></blockquote><p><strong>Q2：ReAct 最常见的失败场景？怎么缓解？</strong></p><blockquote><p>循环（重复同动作）、幻觉工具参数、长上下文遗忘。缓解：最大步数限制、循环检测、把关键结果写入记忆、加校验节点。</p></blockquote><p><strong>Q3：为什么现在很多项目不用重框架而自研核心循环？</strong></p><blockquote><p>重框架抽象多、启动慢、定制难；多数场景核心只是「循环 + 工具 + 记忆」，自研更可控、易调试、成本低。框架适合快速原型。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-RAG检索增强">02-RAG 检索增强</a></p>`,32)])])}const u=e(l,[["render",r]]);export{h as __pageData,u as default};
